import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const enhanceDevotional = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Enhance the following devotional text into a structured format. 
      Input text: "${text}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            scripture: { type: Type.STRING, description: "Relevant biblical scripture" },
            content: { type: Type.STRING, description: "The core devotional message" },
            prayer: { type: Type.STRING, description: "A concluding prayer" },
            meditation: { type: Type.STRING, description: "A short one-sentence meditation" },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "scripture", "content", "prayer", "meditation", "tags"]
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    return result;
  } catch (error) {
    console.error("Gemini Enhancement Error:", error);
    return null;
  }
};

export const getDailyReflections = async (devotional: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Based on this devotional, provide 3 deep reflection questions to help the reader grow spiritually today: "${devotional}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Gemini Reflections Error:", error);
    return ["What stood out to you today?", "How can you apply this to your life?", "Who can you share this with?"];
  }
};

import { DevotionalEntry, UserPreferences } from '../types';
import { INITIAL_DEVOTIONALS } from '../constants';

const STORAGE_KEYS = {
  DEVOTIONALS: 'spirit_meal_devotionals',
  PREFERENCES: 'spirit_meal_prefs',
  ADMIN_MODE: 'spirit_meal_admin'
};

export const storage = {
  getDevotionals: (): DevotionalEntry[] => {
    const data = localStorage.getItem(STORAGE_KEYS.DEVOTIONALS);
    return data ? JSON.parse(data) : INITIAL_DEVOTIONALS;
  },
  saveDevotionals: (devotionals: DevotionalEntry[]) => {
    localStorage.setItem(STORAGE_KEYS.DEVOTIONALS, JSON.stringify(devotionals));
  },
  getPreferences: (): UserPreferences => {
    const data = localStorage.getItem(STORAGE_KEYS.PREFERENCES);
    return data ? JSON.parse(data) : {
      theme: 'light',
      notificationsEnabled: true,
      fontSize: 'base'
    };
  },
  savePreferences: (prefs: UserPreferences) => {
    localStorage.setItem(STORAGE_KEYS.PREFERENCES, JSON.stringify(prefs));
  },
  getAdminMode: (): boolean => {
    return localStorage.getItem(STORAGE_KEYS.ADMIN_MODE) === 'true';
  },
  setAdminMode: (active: boolean) => {
    localStorage.setItem(STORAGE_KEYS.ADMIN_MODE, active ? 'true' : 'false');
  }
};

import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { ICONS } from '../constants';
import { ThemeMode } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  theme: ThemeMode;
  isAdmin: boolean;
}

const Layout: React.FC<LayoutProps> = ({ children, theme, isAdmin }) => {
  const location = useLocation();

  const themeClasses = {
    light: 'bg-stone-50 text-stone-900',
    sepia: 'bg-[#f4ecd8] text-[#5b4636]',
    dark: 'bg-stone-900 text-stone-100'
  };

  const navItem = (path: string, label: string, Icon: React.FC) => {
    const isActive = location.pathname === path;
    return (
      <Link 
        to={path} 
        className={`flex flex-col items-center justify-center space-y-1 transition-colors ${
          isActive ? 'text-amber-700' : 'text-stone-400 hover:text-stone-600'
        }`}
      >
        <Icon />
        <span className="text-[10px] font-medium uppercase tracking-wider">{label}</span>
      </Link>
    );
  };

  return (
    <div className={`min-h-screen flex flex-col ${themeClasses[theme]} transition-colors duration-300`}>
      {/* Header */}
      <header className={`sticky top-0 z-10 px-6 py-4 border-b ${
        theme === 'dark' ? 'border-stone-800 bg-stone-900/90' : 'border-stone-200 bg-white/80'
      } backdrop-blur-md flex justify-between items-center`}>
        <h1 className="text-2xl font-bold tracking-tight text-amber-800 serif-font">Spirit Meal</h1>
        <div className="flex items-center space-x-3">
          {isAdmin && (
            <span className="text-[10px] bg-amber-100 text-amber-800 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest border border-amber-200">
              Admin
            </span>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 pb-24 max-w-2xl mx-auto w-full px-4 sm:px-6">
        {children}
      </main>

      {/* Bottom Navigation */}
      <nav className={`fixed bottom-0 left-0 right-0 z-20 px-6 py-3 border-t ${
        theme === 'dark' ? 'bg-stone-900/95 border-stone-800' : 'bg-white/95 border-stone-200'
      } backdrop-blur-md`}>
        <div className="max-w-md mx-auto flex justify-between items-center">
          {navItem('/', 'Today', ICONS.Home)}
          {navItem('/archive', 'Archive', ICONS.Archive)}
          {isAdmin && navItem('/admin', 'Create', ICONS.Admin)}
          {navItem('/settings', 'Settings', ICONS.Settings)}
        </div>
      </nav>
    </div>
  );
};

export default Layout;

import React, { useState } from 'react';
import { enhanceDevotional } from '../services/geminiService';
import { DevotionalEntry } from '../types';
import { storage } from '../services/storageService';
import { ICONS } from '../constants';

const AdminPanel: React.FC<{ onEntryAdded: () => void }> = ({ onEntryAdded }) => {
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);
  const [entry, setEntry] = useState<Partial<DevotionalEntry> | null>(null);

  const handleEnhance = async () => {
    if (!inputText.trim()) return;
    setLoading(true);
    const enhanced = await enhanceDevotional(inputText);
    if (enhanced) {
      setEntry({
        ...enhanced,
        date: new Date().toISOString().split('T')[0],
        id: Math.random().toString(36).substr(2, 9),
        imageUrl: `https://picsum.photos/seed/${Math.random()}/800/450`
      });
    }
    setLoading(false);
  };

  const handlePublish = () => {
    if (!entry) return;
    const current = storage.getDevotionals();
    storage.saveDevotionals([entry as DevotionalEntry, ...current]);
    setEntry(null);
    setInputText('');
    onEntryAdded();
    alert('Devotional Published!');
  };

  return (
    <div className="space-y-6 pt-6">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200">
        <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
          <ICONS.Admin /> Create New Spirit Meal
        </h2>
        <p className="text-stone-500 text-sm mb-4">
          Paste your plain text devotional here. AI will help format and curate it for the best reader experience.
        </p>
        <textarea
          className="w-full h-40 p-4 rounded-xl border border-stone-300 focus:ring-2 focus:ring-amber-500 focus:border-transparent outline-none transition-all resize-none text-stone-800"
          placeholder="Enter the message for today..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button
          onClick={handleEnhance}
          disabled={loading || !inputText}
          className="mt-4 w-full bg-stone-900 text-white py-3 rounded-xl font-medium flex items-center justify-center gap-2 hover:bg-stone-800 transition-colors disabled:opacity-50"
        >
          {loading ? (
            <span className="animate-spin h-5 w-5 border-2 border-white/30 border-t-white rounded-full" />
          ) : (
            <ICONS.Sparkles />
          )}
          Enhance with Spirit AI
        </button>
      </div>

      {entry && (
        <div className="bg-amber-50 p-6 rounded-2xl border border-amber-200 animate-in fade-in slide-in-from-bottom-4">
          <h3 className="text-xs font-bold uppercase tracking-widest text-amber-800 mb-4">Preview & Review</h3>
          <div className="space-y-4 mb-6">
            <div>
              <label className="text-[10px] font-bold text-stone-400 uppercase">Title</label>
              <input 
                className="w-full bg-transparent border-b border-amber-200 py-1 text-lg font-semibold outline-none" 
                value={entry.title} 
                onChange={e => setEntry({...entry, title: e.target.value})}
              />
            </div>
            <div>
              <label className="text-[10px] font-bold text-stone-400 uppercase">Scripture</label>
              <textarea 
                className="w-full bg-transparent border-b border-amber-200 py-1 text-sm outline-none resize-none" 
                value={entry.scripture} 
                onChange={e => setEntry({...entry, scripture: e.target.value})}
              />
            </div>
            <div>
              <label className="text-[10px] font-bold text-stone-400 uppercase">Content</label>
              <textarea 
                className="w-full bg-transparent border-b border-amber-200 py-1 text-sm outline-none h-32 resize-none" 
                value={entry.content} 
                onChange={e => setEntry({...entry, content: e.target.value})}
              />
            </div>
          </div>
          <button
            onClick={handlePublish}
            className="w-full bg-amber-700 text-white py-3 rounded-xl font-bold shadow-lg shadow-amber-900/20 hover:bg-amber-800 transition-all"
          >
            Publish Daily Entry
          </button>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { DevotionalEntry, ThemeMode } from '../types';
import { getDailyReflections } from '../services/geminiService';

interface Props {
  entry: DevotionalEntry;
  theme: ThemeMode;
  fontSize: string;
}

const DevotionalCard: React.FC<Props> = ({ entry, theme, fontSize }) => {
  const [reflections, setReflections] = useState<string[]>([]);
  const [loadingReflections, setLoadingReflections] = useState(false);

  useEffect(() => {
    const fetchReflections = async () => {
      setLoadingReflections(true);
      const res = await getDailyReflections(entry.content);
      setReflections(res);
      setLoadingReflections(false);
    };
    fetchReflections();
  }, [entry.id, entry.content]);

  const fontSizeClass = {
    sm: 'text-sm',
    base: 'text-base',
    lg: 'text-lg',
    xl: 'text-xl'
  }[fontSize as 'sm' | 'base' | 'lg' | 'xl'] || 'text-base';

  return (
    <div className="py-8 animate-in fade-in duration-700">
      <div className="mb-6">
        <span className="text-xs font-bold uppercase tracking-[0.2em] text-amber-800/60 block mb-2">
          {new Date(entry.date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
        </span>
        <h2 className={`text-3xl md:text-4xl font-bold leading-tight serif-font ${theme === 'dark' ? 'text-white' : 'text-stone-900'}`}>
          {entry.title}
        </h2>
      </div>

      {entry.imageUrl && (
        <img 
          src={entry.imageUrl} 
          alt={entry.title} 
          className="w-full h-56 object-cover rounded-3xl shadow-xl shadow-stone-900/5 mb-8"
        />
      )}

      <div className={`p-6 rounded-2xl border-l-4 border-amber-600 mb-8 italic ${
        theme === 'dark' ? 'bg-stone-800 text-stone-300' : 'bg-amber-50 text-amber-900'
      }`}>
        <p className="font-medium">{entry.scripture}</p>
      </div>

      <article className={`serif-font leading-relaxed ${fontSizeClass} mb-12 ${
        theme === 'dark' ? 'text-stone-300' : 'text-stone-700'
      }`}>
        {entry.content.split('\n').map((para, i) => (
          <p key={i} className="mb-4">{para}</p>
        ))}
      </article>

      {entry.prayer && (
        <div className={`p-8 rounded-3xl border text-center mb-12 ${
          theme === 'dark' ? 'border-stone-800 bg-stone-800/40' : 'border-amber-100 bg-white shadow-sm'
        }`}>
          <h3 className="text-xs font-bold uppercase tracking-widest text-amber-700 mb-4">A Moment of Prayer</h3>
          <p className="text-lg italic serif-font text-stone-500">"{entry.prayer}"</p>
        </div>
      )}

      {entry.meditation && (
        <div className="border-t border-stone-200 pt-8 mb-12 text-center">
          <p className="text-amber-800/70 font-medium tracking-wide">DAILY MEDITATION</p>
          <p className="text-2xl font-light italic mt-2 serif-font">{entry.meditation}</p>
        </div>
      )}

      <section className={`p-8 rounded-3xl ${theme === 'dark' ? 'bg-stone-800/50' : 'bg-stone-100'}`}>
        <h3 className="text-lg font-semibold mb-6 flex items-center gap-2">
          Spirit Reflections
        </h3>
        {loadingReflections ? (
          <div className="space-y-4">
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-full"></div>
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-3/4"></div>
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-5/6"></div>
          </div>
        ) : (
          <ul className="space-y-6">
            {reflections.map((q, i) => (
              <li key={i} className="flex gap-4">
                <span className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-200 text-amber-800 flex items-center justify-center font-bold text-sm">
                  {i + 1}
                </span>
                <p className={`text-sm leading-relaxed ${theme === 'dark' ? 'text-stone-300' : 'text-stone-600'}`}>
                  {q}
                </p>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
};

export default DevotionalCard;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { DevotionalEntry, UserPreferences } from './types';
import { storage } from './services/storageService';
import Layout from './components/Layout';
import DevotionalCard from './components/DevotionalCard';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
  }, []);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const toggleAdmin = () => {
    const newVal = !isAdmin;
    setIsAdmin(newVal);
    storage.setAdminMode(newVal);
  };

  const refreshDevotionals = () => {
    setDevotionals(storage.getDevotionals());
  };

  return (
    <Router>
      <Layout theme={prefs.theme} isAdmin={isAdmin}>
        <Routes>
          <Route path="/" element={
            devotionals.length > 0 ? (
              <DevotionalCard 
                entry={devotionals[0]} 
                theme={prefs.theme} 
                fontSize={prefs.fontSize} 
              />
            ) : (
              <div className="flex flex-col items-center justify-center h-96 text-stone-400">
                <p>Waiting for the morning meal...</p>
              </div>
            )
          } />

          <Route path="/archive" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">Spiritual Library</h2>
              {devotionals.map((entry) => (
                <Link 
                  key={entry.id} 
                  to={`/devotional/${entry.id}`}
                  className={`block p-4 rounded-2xl border transition-all hover:translate-x-1 ${
                    prefs.theme === 'dark' ? 'border-stone-800 bg-stone-800/30 hover:bg-stone-800/60' : 'border-stone-100 bg-white hover:shadow-md'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] uppercase tracking-widest text-amber-700 font-bold">
                        {new Date(entry.date).toLocaleDateString()}
                      </span>
                      <h3 className="font-semibold text-lg mt-1 serif-font">{entry.title}</h3>
                      <p className="text-sm text-stone-500 line-clamp-1 mt-1">{entry.scripture}</p>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          } />

          <Route path="/devotional/:id" element={
            <DevotionalDetail 
              devotionals={devotionals} 
              theme={prefs.theme} 
              fontSize={prefs.fontSize} 
            />
          } />

          <Route path="/admin" element={
            isAdmin ? (
              <AdminPanel onEntryAdded={refreshDevotionals} />
            ) : (
              <div className="p-8 text-center">Access Restricted</div>
            )
          } />

          <Route path="/settings" element={
            <div className="pt-6 space-y-8">
              <h2 className="text-2xl font-bold serif-font">Preferences</h2>

              <section className="space-y-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Reading Mode</h3>
                <div className="grid grid-cols-3 gap-3">
                  {(['light', 'sepia', 'dark'] as const).map(mode => (
                    <button
                      key={mode}
                      onClick={() => updatePrefs({ theme: mode })}
                      className={`py-3 px-4 rounded-xl border-2 transition-all capitalize font-medium ${
                        prefs.theme === mode 
                          ? 'border-amber-600 bg-amber-50 text-amber-900' 
                          : 'border-stone-200 text-stone-500'
                      }`}
                    >
                      {mode}
                    </button>
                  ))}
                </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Text Size</h3>
                <div className="grid grid-cols-4 gap-2">
                  {(['sm', 'base', 'lg', 'xl'] as const).map(size => (
                    <button
                      key={size}
                      onClick={() => updatePrefs({ fontSize: size })}
                      className={`py-2 rounded-xl border transition-all ${
                        prefs.fontSize === size 
                          ? 'bg-stone-900 text-white border-stone-900' 
                          : 'bg-white text-stone-500 border-stone-200'
                      }`}
                    >
                      {size.toUpperCase()}
                    </button>
                  ))}
                </div>
              </section>

              <section className="pt-8 border-t border-stone-200">
                <button
                  onClick={toggleAdmin}
                  className="w-full py-4 px-6 rounded-2xl border border-stone-300 text-stone-600 font-medium hover:bg-stone-50 transition-colors"
                >
                  {isAdmin ? 'Exit Admin Mode' : 'Developer / Admin Access'}
                </button>
              </section>

              <div className="text-center text-xs text-stone-400 py-8">
                Spirit Meal v1.0.0
                <br />
                Crafted for intentional devotion.
              </div>
            </div>
          } />
        </Routes>
      </Layout>
    </Router>
  );
};

const DevotionalDetail: React.FC<{ 
  devotionals: DevotionalEntry[], 
  theme: any, 
  fontSize: any 
}> = ({ devotionals, theme, fontSize }) => {
  const { id } = React.useMemo(() => {
    const hash = window.location.hash;
    const parts = hash.split('/');
    return { id: parts[parts.length - 1] };
  }, [window.location.hash]);

  const entry = devotionals.find(d => d.id === id);

  if (!entry) return <div className="p-8 text-center">Devotional not found</div>;

  return <DevotionalCard entry={entry} theme={theme} fontSize={fontSize} />;
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractDevotionalStructure = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `You are a content extractor. Your goal is to take a raw devotional text and identify its components. 
      CRITICAL RULE: You MUST NOT rewrite, summarize, or refurbish the 'content' field. It must be a verbatim copy of the main body of the text provided.

      Input text: "${text}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "The title of the devotional" },
            scripture: { type: Type.STRING, description: "The specific Bible verse or reference mentioned" },
            content: { type: Type.STRING, description: "The original, untouched main body text" },
            prayer: { type: Type.STRING, description: "A concluding prayer if present, or a short one based on the text if not" },
            meditation: { type: Type.STRING, description: "A short one-sentence key takeaway" },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "scripture", "content", "prayer", "meditation", "tags"]
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    return result;
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    return null;
  }
};

export const getDailyReflections = async (devotional: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Based on this devotional, provide 3 deep reflection questions to help the reader grow spiritually today: "${devotional}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Gemini Reflections Error:", error);
    return ["What stood out to you today?", "How can you apply this to your life?", "Who can you share this with?"];
  }
};

import React, { useState } from 'react';
import { extractDevotionalStructure } from '../services/geminiService';
import { DevotionalEntry } from '../types';
import { storage } from '../services/storageService';
import { ICONS } from '../constants';

const AdminPanel: React.FC<{ onEntryAdded: () => void }> = ({ onEntryAdded }) => {
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);
  const [entry, setEntry] = useState<Partial<DevotionalEntry> | null>(null);
  const [mode, setMode] = useState<'ai' | 'manual'>('ai');

  const handleProcess = async () => {
    if (!inputText.trim()) return;

    if (mode === 'ai') {
      setLoading(true);
      const extracted = await extractDevotionalStructure(inputText);
      if (extracted) {
        setEntry({
          ...extracted,
          date: new Date().toISOString().split('T')[0],
          id: Math.random().toString(36).substr(2, 9),
          imageUrl: `https://picsum.photos/seed/${Math.random()}/800/450`
        });
      }
      setLoading(false);
    } else {
      // Manual mode just puts the whole thing in the content box
      setEntry({
        title: 'Untitled Entry',
        scripture: 'Add scripture here...',
        content: inputText,
        prayer: 'Add prayer here...',
        meditation: 'Add meditation here...',
        tags: [],
        date: new Date().toISOString().split('T')[0],
        id: Math.random().toString(36).substr(2, 9),
        imageUrl: `https://picsum.photos/seed/${Math.random()}/800/450`
      });
    }
  };

  const handlePublish = () => {
    if (!entry || !entry.title || !entry.content) {
      alert('Please fill in at least the title and content.');
      return;
    }
    const current = storage.getDevotionals();
    storage.saveDevotionals([entry as DevotionalEntry, ...current]);
    setEntry(null);
    setInputText('');
    onEntryAdded();
    alert('Devotional Published Successfully!');
  };

  return (
    <div className="space-y-6 pt-6 animate-in fade-in slide-in-from-top-4">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-stone-200">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2 serif-font">
            <ICONS.Admin /> Creator Studio
          </h2>
          <div className="flex bg-stone-100 p-1 rounded-full text-[10px] font-bold uppercase tracking-wider">
            <button 
              onClick={() => setMode('ai')}
              className={`px-3 py-1.5 rounded-full transition-all ${mode === 'ai' ? 'bg-white shadow-sm text-amber-800' : 'text-stone-400'}`}
            >
              AI Structure
            </button>
            <button 
              onClick={() => setMode('manual')}
              className={`px-3 py-1.5 rounded-full transition-all ${mode === 'manual' ? 'bg-white shadow-sm text-amber-800' : 'text-stone-400'}`}
            >
              Pure Manual
            </button>
          </div>
        </div>

        <p className="text-stone-500 text-sm mb-4">
          {mode === 'ai' 
            ? "Paste your text below. AI will separate the title, scripture, and body without changing your words."
            : "Paste your text below. You will manually assign it to the correct fields."}
        </p>

        <textarea
          className="w-full h-64 p-5 rounded-2xl border border-stone-200 bg-stone-50 focus:ring-2 focus:ring-amber-500/20 focus:border-amber-500 outline-none transition-all resize-none text-stone-800 text-sm leading-relaxed"
          placeholder="Paste the daily Spirit Meal text here..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />

        <button
          onClick={handleProcess}
          disabled={loading || !inputText}
          className="mt-4 w-full bg-stone-900 text-white py-4 rounded-2xl font-semibold flex items-center justify-center gap-2 hover:bg-stone-800 active:scale-[0.98] transition-all disabled:opacity-50"
        >
          {loading ? (
            <span className="animate-spin h-5 w-5 border-2 border-white/30 border-t-white rounded-full" />
          ) : (
            mode === 'ai' ? <ICONS.Sparkles /> : null
          )}
          {mode === 'ai' ? 'Extract & Organize' : 'Prepare for Manual Layout'}
        </button>
      </div>

      {entry && (
        <div className="bg-amber-50/50 p-6 rounded-3xl border border-amber-100 animate-in fade-in slide-in-from-bottom-4 shadow-xl shadow-amber-900/5">
          <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-amber-800/60 mb-6 flex items-center justify-between">
            Final Curation Review
            <button onClick={() => setEntry(null)} className="text-stone-400 hover:text-stone-600">Cancel</button>
          </h3>

          <div className="space-y-6">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Title</label>
              <input 
                className="w-full bg-transparent border-b border-amber-200/50 py-2 text-2xl font-bold serif-font text-stone-800 focus:border-amber-500 outline-none transition-all" 
                value={entry.title} 
                onChange={e => setEntry({...entry, title: e.target.value})}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Scripture Reference</label>
              <input 
                className="w-full bg-transparent border-b border-amber-200/50 py-2 text-sm font-medium italic text-amber-900 focus:border-amber-500 outline-none transition-all" 
                value={entry.scripture} 
                onChange={e => setEntry({...entry, scripture: e.target.value})}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Original Content Body</label>
              <textarea 
                className="w-full bg-white/50 p-4 rounded-xl border border-amber-200/50 text-sm leading-relaxed text-stone-700 h-64 focus:border-amber-500 outline-none resize-none transition-all" 
                value={entry.content} 
                onChange={e => setEntry({...entry, content: e.target.value})}
              />
              <p className="text-[10px] text-amber-700/60 italic">This field contains your original text exactly as pasted.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Closing Prayer</label>
                <textarea 
                  className="w-full bg-white/50 p-3 rounded-xl border border-amber-200/50 text-xs text-stone-600 h-24 focus:border-amber-500 outline-none resize-none transition-all" 
                  value={entry.prayer} 
                  onChange={e => setEntry({...entry, prayer: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Short Meditation</label>
                <textarea 
                  className="w-full bg-white/50 p-3 rounded-xl border border-amber-200/50 text-xs text-stone-600 h-24 focus:border-amber-500 outline-none resize-none transition-all" 
                  value={entry.meditation} 
                  onChange={e => setEntry({...entry, meditation: e.target.value})}
                />
              </div>
            </div>
          </div>

          <button
            onClick={handlePublish}
            className="w-full mt-8 bg-amber-700 text-white py-4 rounded-2xl font-bold shadow-lg shadow-amber-900/20 hover:bg-amber-800 active:scale-[0.99] transition-all"
          >
            Publish to Spirit Meal
          </button>
        </div>
      )}
    </div>
  );
};

