const DevotionalDetail: React.FC<{ 
  devotionals: DevotionalEntry[], 
  theme: any, 
  fontSize: any 
}> = ({ devotionals, theme, fontSize }) => {
  const { id } = React.useMemo(() => {
    const hash = window.location.hash;
    const parts = hash.split('/');
